import requests
import json
import pandas as pd
import seaborn as sns
# Constants
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not url or not isinstance(url, str):
        raise Exception("Invalid URL provided.")
    if parameters is None:
        raise Exception("Parameters cannot be None.")

    try:
        response = requests.get(url, params=parameters, headers=HEADERS, verify=False)
        response.raise_for_status()
        data = response.json()
    except Exception as e:
        raise Exception(f"Failed to retrieve data from URL: {e}")

    if not data:
        raise Exception("Empty data received from API.")

    if isinstance(data, dict) and 'results' in data:
        data = data['results']

    if not isinstance(data, list) or len(data) == 0:
        raise Exception("Invalid data format or empty list received.")

    try:
        df = pd.DataFrame(data)
    except Exception as e:
        raise Exception(f"Failed to convert data to DataFrame: {e}")

    if df.empty:
        raise Exception("DataFrame is empty after conversion.")

    numeric_df = df.select_dtypes(include=['number'])

    if numeric_df.empty:
        raise Exception("No numerical columns found in the data for correlation.")

    corr_matrix = numeric_df.corr()

    ax = sns.heatmap(corr_matrix, annot=True, cmap='coolwarm', linewidths=.5)

    return df, ax
